<script setup>
import {useUiText} from "../ui-text";
const ui=useUiText();

import ParameterReset from './ParameterReset.vue';
import {assistantParameterDefaults} from '../../shared/parameter-defaults.mjs';

import AssistantQuality from './AssistantQuality.vue';
import {defaultLlmRepository,recommendedLlmFile,matchingProjectors,isVisionProjector} from '../../shared/llm-recommendation.mjs';
defineProps({hideQuality:Boolean});
import {ref,computed,onMounted,watch} from 'vue';import {FolderOpen,Download,Search,X,RefreshCw} from 'lucide-vue-next';import {useStudio,api} from '../store';
const desktop=window.desktop;const s=useStudio();s.config.llm||={provider:'local',modelDirs:[],model:'',mmproj:'',context:8192,maxTokens:4096,gpuLayers:'auto',temperature:.65,unloadAfter:true,deepseekModel:'deepseek-flash'};const c=computed(()=>s.config.llm),data=ref({models:[]}),key=ref(''),status=ref(''),working=ref(false),downloadOpen=ref(false),query=ref('Qwen GGUF'),repos=ref([]),repo=ref(null),file=ref(''),querying=ref(false);
const refreshing=ref(false);
const downloadingDefault=ref(false),projectorName=ref('');
const projectors=computed(()=>repo.value?.files.filter(f=>isVisionProjector(f.name))||[]);
watch([file,repo],()=>{projectorName.value=matchingProjectors(repo.value?.files||[],file.value)[0]?.name||'';});
watch(()=>c.value.model,model=>{const found=data.value.models.find(m=>m.path===model);if(found)c.value.mmproj=found.projectorPath||'';});
async function finishDownload(){await refresh();const selected=data.value.selection;if(selected?.model?.split(/[/\\]/).at(-1)===c.value.pendingDownloadName){Object.assign(c.value,selected);delete c.value.pendingDownloadName;status.value=selected.mmproj?s.t('主模型和配套视觉模型已下载并校验，已自动选中。','The model and matching vision projector are verified and selected.'):s.t('主模型已下载并校验，已自动选中。','The model is verified and selected.');}}
async function startModelDownload(payload){const result=await api('models/hf/download',payload);if(result.modelName)c.value.pendingDownloadName=result.modelName.split('/').at(-1);status.value=result.projectorName?s.t('主模型与配套视觉模型已加入同一下载任务，完成后自动关联。','The model and matching vision projector are queued together and will be linked automatically.'):s.t('已开始下载，仓库未提供可配套的视觉模型。','Download started. No matching vision projector is provided in this repository.');if(s.install.state==='done'&&c.value.pendingDownloadName)await finishDownload();return result;}

async function downloadRecommended(){downloadingDefault.value=true;try{const source=await api('models/hf/files',{url:defaultLlmRepository}),selected=recommendedLlmFile(source.files);if(!selected)throw Error(s.t('指定仓库暂未提供推荐的量化文件，请在在线找模型中查看。','The recommended quantization is unavailable. Use the model browser.'));await startModelDownload({repo:source.repo,revision:source.revision,name:selected.name,category:'llm'});}finally{downloadingDefault.value=false;}}
watch(()=>s.install.state,async state=>{if(state==='done'&&c.value.pendingDownloadName)await finishDownload();});
const size=n=>n>=1e9?(n/1e9).toFixed(1)+' GB':(n/1e6).toFixed(0)+' MB';
async function refresh(){refreshing.value=true;try{data.value=await api('assistant/models');status.value='模型列表已刷新';}catch(e){status.value=e.message;}finally{refreshing.value=false;}}onMounted(async()=>{await refresh();if(c.value.pendingDownloadName&&s.install.state==='done')await finishDownload();if(c.value.provider==='deepseek'&&data.value.hasKey)await test();});watch(()=>c.value.provider,async mode=>{if(mode==='deepseek'&&data.value.hasKey)await test();});
async function saveKey(){working.value=true;try{await api('assistant/key',{key:key.value});key.value='';data.value.hasKey=true;const result=await api('assistant/test',{});status.value='DeepSeek 已连接，可直接使用';data.value.cloudModels=result.cloudModels;if(result.models.length&&!result.models.includes(c.value.deepseekModel))c.value.deepseekModel=result.models[0];}catch(e){status.value=e.message;}finally{working.value=false;}}
async function test(){working.value=true;try{const result=await api('assistant/test',{});data.value.cloudModels=result.cloudModels;status.value='已更新 '+result.models.length+' 个可用模型';}catch(e){status.value=e.message;}finally{working.value=false;}}
async function folder(){if(!window.desktop?.pickLlmFolder){status.value='请在桌面软件选择模型文件夹。';return;}const path=await window.desktop.pickLlmFolder();if(path){c.value.modelDirs=[...new Set([...(c.value.modelDirs||[]),path])];await refresh();}}
async function search(){querying.value=true;try{repos.value=await api('assistant/hf/search',{query:query.value});}catch(e){s.notify(e.message,'error');}finally{querying.value=false;}}
async function chooseRepo(id){querying.value=true;try{repo.value=await api('models/hf/files',{url:id});file.value=(recommendedLlmFile(repo.value.files)||repo.value.files.find(f=>/\.gguf$/i.test(f.name)&&!isVisionProjector(f.name)&&!/fastmtp/i.test(f.name)))?.name||'';}catch(e){s.notify(e.message,'error');}finally{querying.value=false;}}
async function download(){await s.action(()=>startModelDownload({repo:repo.value.repo,revision:repo.value.revision,name:file.value,category:'llm',projectorName:projectorName.value||undefined}));}
</script>
<template><div class="llm-settings"><button class="quiet parameter-group-reset" @click="Object.assign(c,assistantParameterDefaults)">{{ui("恢复助手默认参数")}}</button><AssistantQuality v-if="!hideQuality"/><div class="segmented"><button :class="{active:c.provider==='local'}" @click="c.provider='local'">{{ui("本地模型")}}</button><button :class="{active:c.provider==='deepseek'}" @click="c.provider='deepseek'">{{ui("DeepSeek 线上")}}</button></div><template v-if="c.provider==='deepseek'"><p class="muted">{{ui("输入 Key 即可使用官方接口。故事描述发送到 DeepSeek，结果自动保存到本机。")}}</p><label><span class="key-label">DeepSeek API Key<button type="button" class="quiet" @click="s.openLink('deepseek')">{{ui("获取 Key ↗")}}</button></span><input v-model="key" type="password" autocomplete="off" :placeholder="ui(&quot;填写 Key；保存在系统加密文件中&quot;)"/></label><div class="button-row"><button class="primary" @click="saveKey" :disabled="working||!key.trim()">{{ui(working?'正在连接…':'保存并连接')}}</button><button class="secondary" v-if="data.hasKey" @click="test" :disabled="working">{{ui("验证连接")}}</button></div><label>{{ui("模型")}}<select v-model="c.deepseekModel"><option v-for="m in data.cloudModels" :value="m.id">{{ui(m.name)}} {{ui(m.input_modalities?.includes('image')?'· 支持看图':'')}}</option><option v-if="!data.cloudModels?.some(m=>m.id===c.deepseekModel)" :value="c.deepseekModel">{{ui(c.deepseekModel==='deepseek-flash'?'DeepSeek V4.1 Flash':c.deepseekModel)}}{{ui(" · 保存 Key 后获取列表")}}</option></select></label><button v-if="data.hasKey" class="secondary" @click="test" :disabled="working" :aria-busy="working"><RefreshCw :size="14"/>{{ui("刷新官方可用模型")}}</button><span v-if="data.hasKey" class="key-saved">{{ui("✓ 已保存 Key，不显示密钥内容")}}</span></template>
 <template v-else><div class="info-note llm-default-model"><strong>{{ui("默认语言模型：Qwen3.8 27B")}}</strong><p>{{ui(s.t('模型下载到本软件自己的目录；仓库提供匹配的视觉模型时会一起下载，完成后自动关联。','Models are saved in this app’s folder. A matching vision projector is downloaded and linked when the repository provides one.'))}}</p></div><label>{{ui("本地 GGUF 模型")}}<select v-model="c.model"><option value="">{{ui("请选择模型")}}</option><option v-for="m in data.models.filter(m=>!m.mmproj&&!/fastmtp/i.test(m.name))" :value="m.path">{{ui(m.name)}} · {{ui(size(m.size))}}</option></select></label><label>{{ui("mmproj（可选，处理图片时使用）")}}<select v-model="c.mmproj"><option value="">{{ui("不加载 · 纯文本分镜")}}</option><option v-for="m in data.models.filter(m=>m.mmproj)" :value="m.path">{{ui(m.name)}} · {{ui(size(m.size))}}</option></select></label><div class="button-row"><button class="secondary" @click="folder"><FolderOpen :size="15"/>{{ui("导入本机模型")}}</button><button class="secondary" @click="desktop?.openLlmFolder?.()"><FolderOpen :size="15"/>{{ui("打开模型目录")}}</button><button class="secondary" @click="refresh" :disabled="refreshing" :aria-busy="refreshing"><RefreshCw :size="15"/>{{ui("刷新")}}</button><button class="primary" :disabled="downloadingDefault||s.install.state==='running'" :aria-busy="downloadingDefault" :title="ui(defaultLlmRepository)" @click="s.action(downloadRecommended)"><Download :size="15"/>{{ui(downloadingDefault?'正在准备…':'下载模型')}}</button><button class="secondary" @click="downloadOpen=true"><Search :size="15"/>{{ui("在线找模型")}}</button></div><button v-if="!data.runtime" class="secondary" @click="s.action(async()=>{await api('assistant/install',{});await refresh()})">{{ui("安装独立 LLM 运行时")}}</button><details><summary>{{ui("高级加载设置")}}</summary><div class="llm-advanced"><p class="info-note">{{ui(data.memoryPlan?.label||'自动检测可用显存，优先 GPU 推理，生图与 LLM 自动错开加载。')}}</p><div class="resettable-field" ><label><span class="parameter-caption">{{ui("KV 缓存")}}</span><select v-model="c.cacheType"><option :value="null">{{ui("自动（推荐）")}}</option><option value="q8_0">{{ui("Q8 · 节省缓存显存")}}</option><option value="f16">{{ui("FP16 · 兼容模式")}}</option></select></label><ParameterReset :model="c" :defaults="assistantParameterDefaults" path="cacheType"/></div><div class="resettable-field" ><label><span class="parameter-caption">{{ui("上下文长度")}}</span><select v-model.number="c.context"><option v-for="n in [2048,4096,8192,16384,32768,65536,131072]" :value="n">{{ui(n.toLocaleString())}} tokens</option></select></label><ParameterReset :model="c" :defaults="assistantParameterDefaults" path="context"/></div><div class="resettable-field" ><label><span class="parameter-caption">{{ui("GPU 卸载")}}</span><select v-model="c.gpuLayers"><option value="auto">{{ui("自动适配显存")}}</option><option value="0">{{ui("CPU（省显存，较慢）")}}</option><option v-for="n in [16,24,32,48,64,999]" :value="String(n)">{{ui(n===999?'全部':n+' 层')}}</option></select></label><ParameterReset :model="c" :defaults="assistantParameterDefaults" path="gpuLayers"/></div><label>{{ui("本机兼容接口（可选）")}}<input v-model="c.endpoint" placeholder="http://127.0.0.1:1234/v1"/></label><p class="muted">{{ui("填写兼容的本机接口；留空使用本软件独立运行时。大模型先用 8K 上下文，显存不足时降低 GPU 层数或上下文。")}}</p></div></details></template><div class="resettable-field" ><label><span class="parameter-caption">{{ui("最大输出长度")}}</span><input type="number" v-model.number="c.maxTokens" min="512" :max="c.context-1800" step="512"/></label><ParameterReset :model="c" :defaults="assistantParameterDefaults" path="maxTokens"/></div><div class="resettable-field" ><label><span class="parameter-caption">{{ui("创意程度")}}</span><input type="range" v-model.number="c.temperature" min="0" max="1.5" step=".05"/></label><ParameterReset :model="c" :defaults="assistantParameterDefaults" path="temperature"/></div><div class="resettable-field" ><label class="inline-check"><input type="checkbox" v-model="c.unloadAfter"/>{{ui("完成后卸载本地 LLM（推荐）")}}</label><ParameterReset :model="c" :defaults="assistantParameterDefaults" path="unloadAfter"/></div><p v-if="status" class="info-note">{{ui(status)}}</p>
 <div v-if="downloadOpen" class="modal-backdrop"><section class="modal llm-model-browser" role="dialog" :aria-label="ui(&quot;在线搜索下载语言模型&quot;)"><div class="modal-dismiss-row"><button class="icon-button" @click="downloadOpen=false"><X/></button></div><div class="modal-title"><h2>{{ui("在线查找 GGUF 模型")}}</h2></div><div class="button-row"><input v-model="query" @keydown.enter="search" :aria-label="ui(&quot;搜索 Hugging Face 语言模型&quot;)" :placeholder="ui(&quot;模型名称，例如 Qwen 8B GGUF&quot;)"/><button class="primary" @click="search" :disabled="querying"><Search :size="16"/>{{ui(querying?'查询中…':'搜索')}}</button></div><div class="llm-download-columns" v-resize-panels="{key:'llm-download',config:s.config,min:[220,250]}"><div class="llm-repo-list"><button v-for="r in repos" @click="chooseRepo(r.id)"><strong>{{ui(r.id)}}</strong><small>↓ {{ui(r.downloads?.toLocaleString())}} · ♥ {{ui(r.likes)}}</small></button></div><div v-if="repo" class="llm-repo-files"><h3>{{ui(repo.repo)}}</h3><label>{{ui(s.t('选择主模型量化版本','Choose model quantization'))}}<select v-model="file"><option v-for="f in repo.files.filter(f=>/\.gguf$/i.test(f.name)&&!isVisionProjector(f.name)&&!/fastmtp/i.test(f.name))" :value="f.name">{{ui(f.name)}} · {{ui(size(f.size))}}</option></select></label><label v-if="projectors.length">{{ui(s.t('配套视觉模型（一起下载）','Matching vision projector (downloaded together)'))}}<select v-model="projectorName" :aria-label="s.t('配套视觉模型','Matching vision projector')"><option value="">{{ui(s.t('自动匹配；无法确定时请选择','Auto-match; select a file if ambiguous'))}}</option><option v-for="f in projectors" :value="f.name">{{f.name}} · {{size(f.size)}}</option></select></label><p v-else class="muted">{{ui(s.t('此仓库未提供视觉模型，将只下载主模型。','This repository provides no vision projector; only the model will be downloaded.'))}}</p><p class="muted">{{ui("通常先选 Q4_K_M / Q4_K_S；小显存可选较小模型。文件固定版本并校验 SHA256，自动测速选择官方或国内镜像源。")}}</p><button class="primary" @click="download" :disabled="!file||s.install.state==='running'">{{ui("下载并校验")}}</button></div></div></section></div></div></template>
